#include "address_map_arm.h"
#include <stdio.h>
extern volatile int MULTIPLICATION_FINISHED;

/***************************************************************************************
 * Booth IRQ - Interrupt Service Routine
 *
 * Since, IRQ is generated by the booth multiplier, we need to clear the interrupt by toggling the ack bit (bit 2) in slv_reg3.
 * After clearing the interrupt, we set the MULTIPLICATION_FINISHED flag to 1.
 ****************************************************************************************/
void booth_ISR(void) {
    volatile int *status = (int *)0xFF20000C;  // reads the data at slv_reg3 base address
    
    printf("Checking the Booth ISR\n");
    int val = *status; // temporarily store the value of slv_reg3 in a variable
    
    // Enable ack
    val |= (1 << 2);      // ack = 1
    *status = val;
    
    // Disable ack
    val = *status;
    val &= ~(1 << 2);     // ack = 0
    *status = val;
    
    // Post-multiplication flag
    MULTIPLICATION_FINISHED = 1;
    printf("Exiting the Booth ISR\n");
    
    return;
}
